//! Writes `src/bindings.ts`, the TypeScript half of the IPC contract:
//! - every type a command sends or receives, generated by ts-rs from the Rust definitions;
//! - `Commands`: each registered command with its argument names and types and its result,
//!   read from the `#[tauri::command]` functions and `generate_handler!` in `lib.rs`.
//!
//! Any `cargo test` regenerates the file (`npm run bindings` runs just this test), and CI fails
//! when the committed copy differs, so a rename on this side breaks `npm run check`, not the app.

use std::collections::{BTreeMap, BTreeSet};
use std::fmt::Write as _;

use syn::punctuated::Punctuated;
use syn::visit::Visit;
use ts_rs::{Config, TS};

use crate::error::{CommandError, ErrorKind};
use crate::miniflux::{Category, Entry, EntryFeed, EntryPage, EntryStatus, Feed, FeedCount, Selection};
use crate::theme::Theme;
use crate::{AppStatus, Settings};

const OUT: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../src/bindings.ts");
/// The commands live here; `include_str!` also rebuilds the test when they change.
const LIB_RS: &str = include_str!("lib.rs");

const HEADER: &str = "\
// Generated from the Rust types and commands by src-tauri/src/bindings.rs. Do not edit:
// run `npm run bindings` after changing them. src/api.ts is the hand-written facade over this file.
";

/// IDs and counts stay far below 2^53, so `i64` is a plain `number` rather than `bigint`.
fn config() -> Config {
    Config::new().with_large_int("number")
}

/// One exported type: its Rust name (as commands spell it), TypeScript name, declaration and dependencies.
struct Exported {
    rust: &'static str,
    ts: String,
    decl: String,
    deps: Vec<String>,
}

fn exported<T: TS + 'static>(rust: &'static str, cfg: &Config) -> Exported {
    Exported {
        rust,
        ts: T::name(cfg),
        decl: format!("{}export {}", T::docs().unwrap_or_default(), T::decl(cfg)),
        deps: T::dependencies(cfg).into_iter().map(|d| d.ts_name).collect(),
    }
}

/// Everything the commands send or receive, in the order the file lists them.
macro_rules! exported {
    ($cfg:expr; $($ty:ident),+ $(,)?) => { vec![$(exported::<$ty>(stringify!($ty), $cfg)),+] };
}

fn types(cfg: &Config) -> Vec<Exported> {
    exported![cfg; AppStatus, Settings, Theme, Category, Feed, FeedCount, EntryStatus, EntryFeed, Entry, EntryPage, Selection, ErrorKind, CommandError]
}

/// A command as the webview calls it: `invoke(name, args)` resolves to `returns`.
#[derive(Debug)]
struct Command {
    name: String,
    /// `(name as Tauri expects it, TypeScript type)`
    args: Vec<(String, String)>,
    returns: String,
}

/// Rust number types that are a plain `number` in TypeScript (see `config()` for `i64`).
const NUMBERS: [&str; 12] = ["i8", "i16", "i32", "i64", "isize", "u8", "u16", "u32", "u64", "usize", "f32", "f64"];

/// Arguments Tauri fills in itself; the webview never passes them.
const INJECTED: [&str; 4] = ["State", "AppHandle", "Window", "WebviewWindow"];

fn last_segment(path: &syn::Path) -> &syn::PathSegment {
    path.segments.last().expect("a path has at least one segment")
}

fn generic_args(seg: &syn::PathSegment) -> Vec<&syn::Type> {
    match &seg.arguments {
        syn::PathArguments::AngleBracketed(a) => a
            .args
            .iter()
            .filter_map(|g| match g {
                syn::GenericArgument::Type(t) => Some(t),
                _ => None,
            })
            .collect(),
        _ => Vec::new(),
    }
}

/// The TypeScript for a Rust type in a command signature. Panics on anything it doesn't know,
/// so a new kind of argument or result gets a deliberate mapping here.
fn ts_type(ty: &syn::Type, known: &BTreeMap<&str, &str>) -> String {
    match ty {
        syn::Type::Tuple(t) if t.elems.is_empty() => "void".into(),
        syn::Type::Path(p) => {
            let seg = last_segment(&p.path);
            let args = generic_args(seg);
            match (seg.ident.to_string().as_str(), args.as_slice()) {
                ("String", []) => "string".into(),
                ("bool", []) => "boolean".into(),
                (n, []) if NUMBERS.contains(&n) => "number".into(),
                ("Vec", [inner]) => format!("{}[]", ts_type(inner, known)),
                ("Option", [inner]) => format!("{} | null", ts_type(inner, known)),
                (name, []) => (*known.get(name).unwrap_or_else(|| {
                    panic!("`{name}` is in a command signature but not exported; add it to types() in bindings.rs")
                }))
                .into(),
                (name, _) => panic!("bindings.rs doesn't know how to map `{name}<…>` to TypeScript"),
            }
        }
        _ => panic!("bindings.rs only maps named types and () in command signatures"),
    }
}

/// What the `invoke` promise resolves to: a command's `Ok` value (its `Err` rejects it with a `CommandError`).
fn ts_result(ret: &syn::ReturnType, known: &BTreeMap<&str, &str>) -> String {
    let syn::ReturnType::Type(_, ty) = ret else { return "void".into() };
    if let syn::Type::Path(p) = &**ty {
        let seg = last_segment(&p.path);
        if seg.ident == "Result" {
            let [ok, err] = generic_args(seg)[..] else { panic!("Result without two type arguments") };
            // Exactly `Error`, the one lib.rs imports from `error`: `io::Error` or `tauri::Error` would not
            // serialize as a `CommandError`.
            let is_crate_error = matches!(err, syn::Type::Path(p) if p.qself.is_none() && p.path.is_ident("Error"));
            assert!(is_crate_error, "commands fail with error::Error (imported as `Error`), sent as a CommandError");
            assert_eq!(ts_type(err, known), "CommandError", "commands fail with error::Error, sent as a CommandError");
            return ts_type(ok, known);
        }
    }
    ts_type(ty, known)
}

/// Tauri's default: command arguments are camelCase on the JavaScript side.
fn camel_case(snake: &str) -> String {
    let mut parts = snake.split('_');
    let mut out = parts.next().unwrap_or_default().to_owned();
    for part in parts {
        let mut chars = part.chars();
        if let Some(first) = chars.next() {
            out.extend(first.to_uppercase());
            out.push_str(chars.as_str());
        }
    }
    out
}

fn is_command_attr(attr: &syn::Attribute) -> bool {
    let names: Vec<String> = attr.path().segments.iter().map(|s| s.ident.to_string()).collect();
    if names != ["tauri", "command"] {
        return false;
    }
    // `rename_all`, `async` etc. would change what the webview sees; teach this file about them first.
    assert!(matches!(attr.meta, syn::Meta::Path(_)), "bindings.rs only understands a bare #[tauri::command]");
    true
}

fn command(f: &syn::ItemFn, known: &BTreeMap<&str, &str>) -> Command {
    let args = f
        .sig
        .inputs
        .iter()
        .filter_map(|input| {
            let syn::FnArg::Typed(arg) = input else { panic!("commands are free functions") };
            if let syn::Type::Path(p) = &*arg.ty {
                if INJECTED.contains(&last_segment(&p.path).ident.to_string().as_str()) {
                    return None;
                }
            }
            let syn::Pat::Ident(name) = &*arg.pat else { panic!("command arguments need plain names") };
            Some((camel_case(&name.ident.to_string()), ts_type(&arg.ty, known)))
        })
        .collect();
    Command { name: f.sig.ident.to_string(), args, returns: ts_result(&f.sig.output, known) }
}

/// The names inside `tauri::generate_handler![…]`.
#[derive(Default)]
struct Handler(Vec<Vec<String>>);

impl<'ast> Visit<'ast> for Handler {
    fn visit_macro(&mut self, mac: &'ast syn::Macro) {
        if last_segment(&mac.path).ident == "generate_handler" {
            let paths = mac
                .parse_body_with(Punctuated::<syn::Path, syn::Token![,]>::parse_terminated)
                .expect("generate_handler! lists command paths");
            self.0.push(paths.iter().map(|p| last_segment(p).ident.to_string()).collect());
        }
    }
}

/// The segments of a plain `use a::b::C;` (empty for groups, globs and renames).
fn use_path(tree: &syn::UseTree) -> Vec<String> {
    match tree {
        syn::UseTree::Path(p) => {
            let rest = use_path(&p.tree);
            if rest.is_empty() {
                return rest;
            }
            std::iter::once(p.ident.to_string()).chain(rest).collect()
        }
        syn::UseTree::Name(n) => vec![n.ident.to_string()],
        _ => Vec::new(),
    }
}

/// The registered commands, in `generate_handler!` order.
fn commands(known: &BTreeMap<&str, &str>) -> Vec<Command> {
    let file = syn::parse_file(LIB_RS).expect("lib.rs parses");
    let imports_error =
        file.items.iter().any(|item| matches!(item, syn::Item::Use(u) if use_path(&u.tree) == ["error", "Error"]));
    assert!(imports_error, "lib.rs imports `use error::Error;`, the error every command returns");
    let mut defined: BTreeMap<String, Command> = file
        .items
        .iter()
        .filter_map(|item| match item {
            syn::Item::Fn(f) if f.attrs.iter().any(is_command_attr) => Some(command(f, known)),
            _ => None,
        })
        .map(|c| (c.name.clone(), c))
        .collect();

    let mut handler = Handler::default();
    handler.visit_file(&file);
    let [registered] = &handler.0[..] else { panic!("expected exactly one generate_handler! in lib.rs") };

    let defined_names: BTreeSet<&String> = defined.keys().collect();
    let registered_names: BTreeSet<&String> = registered.iter().collect();
    assert_eq!(defined_names, registered_names, "every #[tauri::command] in lib.rs is registered, and only those");
    assert_eq!(registered.len(), registered_names.len(), "a command is registered twice");

    registered.iter().map(|name| defined.remove(name).expect("checked above")).collect()
}

fn render() -> String {
    let cfg = config();
    let types = types(&cfg);
    let names: BTreeSet<&str> = types.iter().map(|t| t.ts.as_str()).collect();
    for t in &types {
        for dep in &t.deps {
            assert!(names.contains(dep.as_str()), "{} uses {dep}; add it to types() in bindings.rs", t.ts);
        }
    }
    let mut known: BTreeMap<&str, &str> = types.iter().map(|t| (t.rust, t.ts.as_str())).collect();
    // Commands fail with `error::Error`, whose `Serialize` sends a `CommandError`.
    known.insert("Error", "CommandError");

    let mut out = String::from(HEADER);
    for t in &types {
        out.push('\n');
        out.push_str(&t.decl);
        out.push('\n');
    }

    out.push_str(
        "\n/** Every command in `generate_handler!`: the arguments `invoke` takes (camelCase, as Tauri expects) \
         and what it resolves to. A failing command rejects with a `CommandError`. */\nexport type Commands = {\n",
    );
    for c in commands(&known) {
        let args = if c.args.is_empty() {
            "Record<string, never>".to_owned()
        } else {
            let fields: Vec<String> = c.args.iter().map(|(name, ty)| format!("{name}: {ty}")).collect();
            format!("{{ {} }}", fields.join("; "))
        };
        writeln!(out, "  {}: {{ args: {args}; returns: {} }};", c.name, c.returns).expect("writing to a String");
    }
    out.push_str("};\n");
    // ts-rs leaves a space after `{` when a field has docs.
    out.lines().map(|line| format!("{}\n", line.trim_end())).collect()
}

#[test]
fn export_bindings() {
    std::fs::write(OUT, render()).expect("write src/bindings.ts");
}

#[test]
fn command_arguments_are_camel_case() {
    assert_eq!(camel_case("selection"), "selection");
    assert_eq!(camel_case("feed_id"), "feedId");
    assert_eq!(camel_case("a_b_c"), "aBC");
}
